import{_ as a,o as e,c as r,a2 as n}from"./chunks/framework.D66Xq0Kv.js";const u=JSON.parse('{"title":"06-1 入门完成以后怎么继续：选一条路，不要同时学十个框架","description":"","frontmatter":{},"headers":[],"relativePath":"06-career/index.md","filePath":"06-career/index.md","lastUpdated":1791601077000}'),l={name:"06-career/index.md"};function s(i,t,o,p,d,c){return e(),r("div",null,[...t[0]||(t[0]=[n(`<h1 id="_06-1-入门完成以后怎么继续-选一条路-不要同时学十个框架" tabindex="-1">06-1 入门完成以后怎么继续：选一条路，不要同时学十个框架 <a class="header-anchor" href="#_06-1-入门完成以后怎么继续-选一条路-不要同时学十个框架" aria-label="Permalink to &quot;06-1 入门完成以后怎么继续：选一条路，不要同时学十个框架&quot;">​</a></h1><blockquote><p><strong>本课目标</strong>：做完 Escrow 后，知道自己下一阶段该学什么、怎样练习、哪些知识暂时不用碰。你不需要立刻掌握 DeFi、MEV 或跨链。</p></blockquote><h2 id="先检查你是否真的-学完基础" tabindex="-1">先检查你是否真的“学完基础” <a class="header-anchor" href="#先检查你是否真的-学完基础" aria-label="Permalink to &quot;先检查你是否真的“学完基础”&quot;">​</a></h2><p>不看前文回答：</p><ol><li>钱包、地址、私钥、合约地址分别是什么？</li><li>为什么给状态加 1，和读取当前数字不是同一种操作？</li><li>你能在 Remix VM 部署 Counter，切换账号复现一次权限错误吗？</li><li>你能运行 <code>forge test -vv</code>，解释三条 Escrow 测试为什么通过吗？</li><li>如果卖家拒收 ETH，这个教程项目能解决问题吗？</li></ol><p>如果还有一两个问题回答不出来，<strong>回到对应课程重做一次，比直接冲进“高阶项目”更有效</strong>。</p><h2 id="路线-a-专门做智能合约开发" tabindex="-1">路线 A：专门做智能合约开发 <a class="header-anchor" href="#路线-a-专门做智能合约开发" aria-label="Permalink to &quot;路线 A：专门做智能合约开发&quot;">​</a></h2><p>适合：喜欢业务规则、权限状态机、安全测试，希望以后写合约。</p><p>建议顺序：</p><table tabindex="0"><thead><tr><th>顺序</th><th>学什么</th><th>做出什么</th></tr></thead><tbody><tr><td>1</td><td>加深 Solidity 类型、映射、事件、错误</td><td>扩展 Counter / Notebook</td></tr><tr><td>2</td><td>Foundry 的不同角色与失败测试</td><td>自己写一条 Unauthorized 测试</td></tr><tr><td>3</td><td>Fuzz 与时间、资金边界</td><td>检查退款边界</td></tr><tr><td>4</td><td>OpenZeppelin 的标准库与角色模型</td><td>在测试项目演示角色限制</td></tr><tr><td>5</td><td>安全复盘</td><td>写一份“为什么我的合约不能管理真钱”的说明</td></tr><tr><td>6</td><td>再接触代理升级、存储布局等</td><td>阅读成熟项目，不急于自己创造协议</td></tr></tbody></table><p>初学者常犯的错误是直接复制一份“DEX、DAO、发币”大项目，能运行却根本看不懂。推荐先把一个小合约的<strong>正常路径与失败路径</strong>讲清楚。</p><h2 id="路线-b-web3-后端-全栈" tabindex="-1">路线 B：Web3 后端 / 全栈 <a class="header-anchor" href="#路线-b-web3-后端-全栈" aria-label="Permalink to &quot;路线 B：Web3 后端 / 全栈&quot;">​</a></h2><p>适合：已有 Python、Flask、数据库经验，想把合约接入产品。</p><p>先理解系统分工：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>网页按钮 / 钱包签名</span></span>
<span class="line"><span>          ↓</span></span>
<span class="line"><span>区块链 RPC ──调用──&gt; Solidity 合约</span></span>
<span class="line"><span>          │</span></span>
<span class="line"><span>          └──链下后端监听事件、核对回执</span></span>
<span class="line"><span>                          ↓</span></span>
<span class="line"><span>                        数据库</span></span>
<span class="line"><span>                          ↓</span></span>
<span class="line"><span>                       业务页面</span></span></code></pre></div><p>下一步的最小 DApp 可以做：</p><ol><li>网页连接测试钱包。</li><li>读取 Counter 合约的 <code>count</code>。</li><li>点击按钮发出 <code>increase</code> 交易。</li><li>分别显示“等待用户签名”“交易已广播”“执行成功或失败”。</li><li>读最新状态，处理用户拒绝签名、网络错误和错误链 ID。</li></ol><p>可以用 viem 或 ethers.js，<strong>先选一种</strong>。后端如果记录链上事件，还要考虑确认数、重组、幂等、断点续传——这一点与你过去的异步任务/数据库经验关系很大。</p><p>本手册 v0.2 计划加入最小 viem DApp，但<strong>当前 v0.1 并没有把完整可运行 DApp 当作已完成内容</strong>。</p><h2 id="路线-c-安全测试和审计方向" tabindex="-1">路线 C：安全测试和审计方向 <a class="header-anchor" href="#路线-c-安全测试和审计方向" aria-label="Permalink to &quot;路线 C：安全测试和审计方向&quot;">​</a></h2><p>适合：喜欢找边界条件、调试、读其他人的合约代码。</p><p>你的训练顺序可以是：</p><ol><li>看懂权限、状态、时间、外部调用这四种危险点。</li><li>在本地隔离环境里构造失败用例。</li><li>用调用轨迹定位哪个条件没检查。</li><li>写出“漏洞影响、复现步骤、修复方式、修复后测试”。</li><li>后续再学签名重放、预言机异常、MEV、经济攻击。</li></ol><p>不要在未知授权的主网合约上测试真实资金攻击。安全学习以本地与获得明确授权的环境为准。</p><h2 id="应该保留怎样的作品集" tabindex="-1">应该保留怎样的作品集？ <a class="header-anchor" href="#应该保留怎样的作品集" aria-label="Permalink to &quot;应该保留怎样的作品集？&quot;">​</a></h2><p>建议把你的项目 README 写成五段：</p><ul><li><strong>业务目标</strong>：一笔订单如何存入、放款、退款？</li><li><strong>技术栈</strong>：Solidity、Foundry、测试环境。</li><li><strong>架构和状态图</strong>：四种状态、三类角色。</li><li><strong>测试证据</strong>：你实际执行的命令和结果，尤其是反向测试。</li><li><strong>已知限制</strong>：没有真实交付判定、争议仲裁和专业审计。</li></ul><p>不要只放“编译成功”的截图；面试时能解释一个拒收 ETH 的失败场景，更能证明你理解了代码。</p><h2 id="官方资料作为进一步查阅-不要一口气全啃" tabindex="-1">官方资料作为进一步查阅，不要一口气全啃 <a class="header-anchor" href="#官方资料作为进一步查阅-不要一口气全啃" aria-label="Permalink to &quot;官方资料作为进一步查阅，不要一口气全啃&quot;">​</a></h2><ul><li><a href="https://docs.soliditylang.org/" target="_blank" rel="noreferrer">Solidity 官方文档</a>：查语法与行为。</li><li><a href="https://getfoundry.sh/" target="_blank" rel="noreferrer">Foundry Book</a>：查工具和测试命令。</li><li><a href="https://ethereum.org/en/developers/docs/" target="_blank" rel="noreferrer">Ethereum 开发者文档</a>：查交易、账户、网络概念。</li><li><a href="https://docs.openzeppelin.com/contracts/" target="_blank" rel="noreferrer">OpenZeppelin Contracts</a>：查标准实现。</li><li><a href="https://scs.owasp.org/" target="_blank" rel="noreferrer">OWASP Smart Contract Security</a>：查安全风险分类。</li></ul><p><strong>完成标准</strong>：能讲一个自己的小项目，知道它解决什么、没有解决什么，不把“本地跑通”说成“主网安全”。</p><p>下一课：<a href="/06-career/interview">15 个知识点自测，先自答再看参考思路</a>。</p>`,32)])])}const g=a(l,[["render",s]]);export{u as __pageData,g as default};
